foreach($regexFrom as $idx => $from){
    $from = trim((string)$from);
    if($from === '') continue;
    $to = trim((string)($regexTo[$idx] ?? ''));
    //валидация: синтаксис + защита от катастрофического бэктрекинга
    $oldLimit = ini_set('pcre.backtrack_limit', 1000);
    $valid = @preg_match($from, '') !== false;
    $t0 = microtime(true);
    if($valid) @preg_replace($from, $to, 'https://example.com/test-page/');
    ini_set('pcre.backtrack_limit', $oldLimit);
    if(!$valid || microtime(true) - $t0 > 0.05) continue; //опасный/невалидный паттерн не сохраняем
    $regexRules[] = ['FROM' => $from, 'TO' => $to];
    if(count($regexRules) >= CanonicalHandler::REGEX_MAX_RULES) break;
}
